DEMO=[('dtu','DTU Undergraduate Admissions (Demo)','https://dtu.ac.in/','OFFICIAL_COLLEGE','VERY_HIGH'),('mait','MAIT Academics (Demo)','https://mait.ac.in/','OFFICIAL_COLLEGE','VERY_HIGH'),('bits-pilani','BITS Pilani Academic Brochure (Demo)','https://www.bits-pilani.ac.in/','OFFICIAL_PDF','HIGH'),('nit-trichy','NIT Trichy Campus Information (Demo)','https://www.nitt.edu/','OFFICIAL_COLLEGE','VERY_HIGH')]
def seed(db):
 """Idempotent: adds missing colleges and sources without touching existing rows."""
 existing={c.id for c in db.query(College).all()}
 for x in COLLEGES:
  if x[0] not in existing: db.add(College(id=x[0],name=x[1],category=x[2],city=x[3],state=x[4],official_domain=x[5]))
 db.commit()
 urls={(s.college_id,s.source_url) for s in db.query(Source).all()}
 for x in DEMO:
  if (x[0],x[2]) not in urls: db.add(Source(college_id=x[0],source_name=x[1],source_url=x[2],source_type=x[3],authority_level=x[4],status='DEMO_READY',is_demo=True))
 for x in PILOT_SOURCES:
  if (x['college_id'],x['source_url']) not in urls: db.add(Source(status='ACTIVE',is_demo=False,**x))
 # Backfill the DEMO label on databases created before Phase 5.
 for s in db.query(Source).filter(Source.status=='DEMO_READY',Source.is_demo.is_(None)): s.is_demo=True
 for s in db.query(Source).filter(Source.is_demo.is_(None)): s.is_demo=False
 db.commit()
